{
  "story": "Recursive functions push a new activation record onto the call stack with each self-call until reaching the base case, then pop them back off in reverse order.",
  "aha": {
    "stateId": "base",
    "observation": "The base case halts new stack frame creation and triggers the return phase."
  },
  "layout": {
    "preset": "stepper",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    },
    {
      "id": "prog",
      "kind": "progress",
      "bind": {
        "completedBefore": "inputs.stepIndex"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Stack Step",
      "options": [
        "call1",
        "call2",
        "base",
        "return1",
        "return2"
      ]
    }
  ],
  "data": {
    "variants": [
      {
        "regions": [
          {
            "id": "frame3",
            "label": "Frame 3: fact(1)",
            "values": ["n = 1", "return 1"]
          },
          {
            "id": "frame2",
            "label": "Frame 2: fact(2)",
            "values": ["n = 2", "wait 2 * fact(1)"]
          },
          {
            "id": "frame1",
            "label": "Frame 1: fact(3)",
            "values": ["n = 3", "wait 3 * fact(2)"]
          },
          {
            "id": "global",
            "label": "Global Scope",
            "values": ["fact(3) invoked"]
          }
        ],
        "states": [
          {
            "id": "call1",
            "label": "First Call",
            "short": "fact(3)",
            "sentence": "Initial call pushes fact(3) onto the stack.",
            "why": "Allocates local variable n=3.",
            "active": ["global", "frame1"],
            "calloutRegion": "frame1",
            "readouts": [
              {
                "id": "depth",
                "label": "Stack Depth",
                "value": "1"
              }
            ]
          },
          {
            "id": "call2",
            "label": "Recursive Call",
            "short": "fact(2)",
            "sentence": "fact(3) calls fact(2), pushing a new frame.",
            "why": "Suspends frame 1 waiting for frame 2.",
            "active": ["frame1", "frame2"],
            "calloutRegion": "frame2",
            "readouts": [
              {
                "id": "depth",
                "label": "Stack Depth",
                "value": "2"
              }
            ]
          },
          {
            "id": "base",
            "label": "Base Case",
            "short": "fact(1)",
            "sentence": "fact(1) hits the base case and returns 1 immediately.",
            "why": "No further recursive calls are made.",
            "active": ["frame2", "frame3"],
            "calloutRegion": "frame3",
            "readouts": [
              {
                "id": "depth",
                "label": "Stack Depth",
                "value": "3"
              }
            ]
          },
          {
            "id": "return1",
            "label": "First Return",
            "short": "Pop fact(1)",
            "sentence": "fact(1) finishes, popping its frame and returning 1.",
            "why": "Unlocks waiting frame 2 computation.",
            "active": ["frame2"],
            "calloutRegion": "frame3",
            "readouts": [
              {
                "id": "depth",
                "label": "Stack Depth",
                "value": "2"
              }
            ]
          },
          {
            "id": "return2",
            "label": "Final Return",
            "short": "Pop fact(2)",
            "sentence": "fact(2) and fact(3) resolve, emptying the stack.",
            "why": "Final result 6 is produced.",
            "active": ["global"],
            "calloutRegion": "frame1",
            "readouts": [
              {
                "id": "depth",
                "label": "Stack Depth",
                "value": "0"
              }
            ]
          }
        ]
      }
    ]
  }
}
